{"cmd":"python3 - <<'PY'
import json
import re
from docx import Document

TEMPLATE = 'offer_letter_template.docx'
DATA = 'employee_data.json'
OUTPUT = 'offer_letter_filled.docx'

with open(DATA, 'r') as f:
    data = json.load(f)

include_relocation = str(data.get('RELOCATION_PACKAGE', '')).strip().lower() in {'yes', 'true', '1'}

start_marker = '{{IF_RELOCATION}}'
end_marker = '{{END_IF_RELOCATION}}'

pattern = re.compile(r'\{\{([A-Z_]+)\}\}')

def replace_in_paragraph(para):
    text = para.text
    if not text:
        return

    new_text = text

    if start_marker in new_text and end_marker in new_text:
        start_idx = new_text.find(start_marker)
        end_idx = new_text.find(end_marker) + len(end_marker)
        if include_relocation:
            # Remove markers but keep content
            new_text = new_text.replace(start_marker, '').replace(end_marker, '')
        else:
            # Remove content between markers (inclusive)
            new_text = new_text[:start_idx] + new_text[end_idx:]

    # Replace placeholders in remaining text
    def repl(match):
        key = match.group(1)
        return str(data.get(key, match.group(0)))

    new_text = pattern.sub(repl, new_text)

    if new_text != text and para.runs:
        para.runs[0].text = new_text
        for run in para.runs[1:]:
            run.text = ''


def process_table(table):
    for row in table.rows:
        for cell in row.cells:
            for para in cell.paragraphs:
                replace_in_paragraph(para)
            for nested in cell.tables:
                process_table(nested)


doc = Document(TEMPLATE)

# Body paragraphs
for para in doc.paragraphs:
    replace_in_paragraph(para)

# Tables (including nested)
for table in doc.tables:
    process_table(table)

# Headers/footers
for section in doc.sections:
    for para in section.header.paragraphs:
        replace_in_paragraph(para)
    for para in section.footer.paragraphs:
        replace_in_paragraph(para)

# Save output

doc.save(OUTPUT)
print('Saved', OUTPUT)
PY"}

